trait Suspendable { var suspended: Boolean = false
  def toggle(): Unit = suspended = !suspended }

class Ball extends GameItem with Suspendable with Runnable {   // one instance
  override def click(): Unit = toggle()
  override def run(): Unit   = while (!suspended) { draw(); step() }
}

val ball = new Ball
ball.suspended = true     // linearisation: the class's members win over trait defaults
